-- Synthetic existing installation derived from repository entities; no production data.
CREATE TABLE families (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar NOT NULL, "inviteCode" varchar NOT NULL UNIQUE, "createdAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE profiles (id varchar PRIMARY KEY, email varchar NOT NULL, "displayName" varchar, "familyId" uuid REFERENCES families(id) ON DELETE SET NULL, "familyRole" varchar NOT NULL DEFAULT 'member', "createdAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar NOT NULL UNIQUE, color varchar, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar NOT NULL, unit varchar, "categoryId" uuid REFERENCES categories(id) ON DELETE SET NULL, "imageUrl" varchar, "userId" varchar, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE shopping_lists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar NOT NULL, "userId" varchar, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE list_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "shoppingListId" uuid NOT NULL REFERENCES shopping_lists(id) ON DELETE CASCADE, "productId" uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, quantity numeric(10,2), unit varchar, notes varchar, "isPurchased" boolean NOT NULL DEFAULT false, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE shopping_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "shoppingListId" uuid REFERENCES shopping_lists(id) ON DELETE SET NULL, status varchar NOT NULL DEFAULT 'active', "completedAt" timestamp, "receiptUrl" varchar, "receiptAnalysis" jsonb, "startedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE session_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "sessionId" uuid NOT NULL REFERENCES shopping_sessions(id) ON DELETE CASCADE, "productId" uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, quantity numeric(10,2), unit varchar, notes varchar, "isPurchased" boolean NOT NULL DEFAULT false, price numeric(10,2), "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE hidden_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" varchar NOT NULL, "productId" varchar NOT NULL, "createdAt" timestamp NOT NULL DEFAULT now());
CREATE INDEX legacy_list_owner_idx ON shopping_lists ("userId");
CREATE INDEX legacy_items_list_idx ON list_items ("shoppingListId");
